import type { RuleTester } from "oxlint/plugins-dev";

// oxlint does not export the rule type, so extract it from the RuleTester signature.
type Rule = Parameters<RuleTester["run"]>[1];

// Requires `identifierPrefix` for `createRoot` of `react-dom/client`.
// When another React root (e.g. a global navigation in the header) is on the same page,
// ids generated by `useId` can collide across roots and break `htmlFor` of `label` and so on.
export const requireIdentifierPrefix: Rule = {
  meta: {
    type: "problem",
    messages: {
      missing:
        "Specify `identifierPrefix` for `createRoot`. Otherwise, ids generated by `useId` may collide with those of another React root on the same page.",
    },
    schema: [],
  },
  create(context) {
    // Local names of `createRoot` imported from `react-dom/client`
    const createRootNames = new Set<string>();
    return {
      ImportDeclaration(node) {
        if (node.source.value !== "react-dom/client") {
          return;
        }
        for (const specifier of node.specifiers) {
          if (
            specifier.type === "ImportSpecifier" &&
            specifier.imported.type === "Identifier" &&
            specifier.imported.name === "createRoot"
          ) {
            createRootNames.add(specifier.local.name);
          }
        }
      },
      CallExpression(node) {
        if (
          node.callee.type !== "Identifier" ||
          !createRootNames.has(node.callee.name)
        ) {
          return;
        }
        const options = node.arguments[1];
        if (options === undefined) {
          context.report({ node, messageId: "missing" });
          return;
        }
        // Options passed as a variable cannot be inspected, so allow them.
        if (options.type !== "ObjectExpression") {
          return;
        }
        const hasIdentifierPrefix = options.properties.some((property) => {
          // Spread properties cannot be inspected either, so allow them.
          if (property.type === "SpreadElement") {
            return true;
          }
          return (
            property.key.type === "Identifier" &&
            property.key.name === "identifierPrefix"
          );
        });
        if (!hasIdentifierPrefix) {
          context.report({ node, messageId: "missing" });
        }
      },
    };
  },
};
